package com.aistock.prediction.marketuse;
import com.aistock.common.*;import com.aistock.common.marketlifecycle.MarketLifecycleContract;import jakarta.servlet.http.HttpServletRequest;import java.util.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.util.MultiValueMap;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/internal/v1/market-version-use-proofs")
public final class MarketUseProofController {
 private final MarketUseOwnerService owner;private final PredictionMarketUseOwner predictions;private final ComparisonMarketUseOwner comparisons;private final PortfolioMarketUseOwner portfolios;
 public MarketUseProofController(MarketUseOwnerService owner){this(owner,null,null);}
 public MarketUseProofController(MarketUseOwnerService owner,PredictionMarketUseOwner predictions){this(owner,predictions,null);}
 public MarketUseProofController(MarketUseOwnerService owner,PredictionMarketUseOwner predictions,ComparisonMarketUseOwner comparisons){this(owner,predictions,comparisons,null);}
 @Autowired public MarketUseProofController(MarketUseOwnerService owner,PredictionMarketUseOwner predictions,ComparisonMarketUseOwner comparisons,PortfolioMarketUseOwner portfolios){this.portfolios=portfolios;this.comparisons=comparisons;this.owner=owner;this.predictions=predictions;}
 @GetMapping("/capabilities") public ApiResponse<?> capabilities(HttpServletRequest request){if(!request.getParameterMap().isEmpty())throw MarketLifecycleContract.invalid();var enabled=new ArrayList<String>();if(owner.enabled())enabled.add("STOCK_ANALYSIS");if(predictions!=null)for(var p:List.of("FORECAST","PREDICTION_VERIFICATION"))if(predictions.enabled(p))enabled.add(p);if(comparisons!=null&&comparisons.enabled())enabled.add("COMPARISON");if(portfolios!=null&&portfolios.enabled())enabled.add("PORTFOLIO_VALUATION");return ApiResponse.success(Map.of("protocolVersion",MarketLifecycleContract.PROTOCOL,"supportedPurposes",List.of("STOCK_ANALYSIS","FORECAST","PREDICTION_VERIFICATION","COMPARISON","PORTFOLIO_VALUATION"),"enabledPurposes",enabled,"consumerIntegration","PARTIAL","actionsEnabled",false),TraceIds.normalize(request.getHeader("X-Trace-Id")));}
 @GetMapping("/{purpose}/{operation}") public ApiResponse<?> proof(@PathVariable String purpose,@PathVariable UUID operation,@RequestParam MultiValueMap<String,String> query,HttpServletRequest request){if(!query.keySet().equals(Set.of("generation"))||query.get("generation").size()!=1)throw MarketLifecycleContract.invalid();var value="STOCK_ANALYSIS".equals(purpose)?owner.proof(purpose,operation,query.getFirst("generation")):"COMPARISON".equals(purpose)?comparisons==null?null:comparisons.proof(operation,query.getFirst("generation")):"PORTFOLIO_VALUATION".equals(purpose)?portfolios==null?null:portfolios.proof(operation,query.getFirst("generation")):predictions==null?null:predictions.proof(purpose,operation,query.getFirst("generation"));if(value==null)throw MarketUseClient.unavailable();return ApiResponse.success(value,TraceIds.normalize(request.getHeader("X-Trace-Id")));}
}
